    public static List<AtlasWaypoint> getAtlasApiResponse() {
        HttpClient client = HttpClient.newBuilder().followRedirects(HttpClient.Redirect.ALWAYS).connectTimeout(Duration.ofSeconds(2L)).build();
        try {
            HttpRequest req = HttpRequest.newBuilder().uri(URI.create("https://api.blackportal.cloud/api/locations")).headers("User-Agent", "XaeroPlus/" + XaeroPlus.XP_VERSION + "+" + XaeroPlus.MC_VERSION).timeout(Duration.ofSeconds(10L)).GET().build();
            HttpResponse<String> response = client.send(req, HttpResponse.BodyHandlers.ofString());
            Gson gson = new GsonBuilder().disableHtmlEscaping().setLenient().create();
            return (List)gson.fromJson(response.body(), (TypeToken)new TypeToken<List<AtlasWaypoint>>(){});
        }
        catch (Exception e) {
            XaeroPlus.LOGGER.error("Failed to get Atlas API response", (Throwable)e);
            return Collections.emptyList();
        }
    }

    public record AtlasWaypoint(String name, Integer x, Integer y, Integer z, Integer dimension) {
        public boolean isValid() {
            return this.name != null && this.x != null && this.z != null && this.dimension != null && this.dimension >= 0 && this.dimension <= 2;
        }
    }
